package dev.logisim.mobile.core

import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertIs

/** These JSON files are generated by the companion's actual Yosys pipeline. */
class HdlImportIntegrationTest {
    private val registry = ComponentCatalog.registry.withDefinitions(
        GatesLibrary.definitions() + WiringLibrary.definitions() + SequentialLibrary.definitions)
    private fun fixture(name: String): String = sequenceOf(File("../fixtures/hdl/import/$name"),
        File("fixtures/hdl/import/$name")).first { it.isFile }.readText()

    private fun imported(name: String, source: String): CircuitProject {
        val result = HdlNativeImporter.importJson(fixture("$name.yosys.json"), listOf(HdlInputFile(source, fixture(source))), registry = registry)
        return assertIs<HdlImportResult.Success>(result, result.toString()).project
    }

    @Test fun realYosysHierarchyAndTwoBitCounterMatchExecutedNetlist() {
        val project = imported("hierarchy_counter", "hierarchy_counter.v")
        assertEquals(setOf("hdl_hierarchy_counter", "hdl_and_bus2"), project.circuits.map { it.name }.toSet())
        val inputs = project.mainCircuit.components.filter { it.kind == ComponentKind.INPUT }.associateBy { it.label }
        val outputs = project.mainCircuit.components.filter { it.kind == ComponentKind.OUTPUT }.associateBy { it.label }
        val simulator = CircuitSimulator(registry = registry)
        fun sample(previous: SimulationState, clock: Int, reset: Int = 0, a: Int = 3, b: Int = 2): SimulationState =
            simulator.settle(project, previous, vectorInputs = mapOf(
                inputs.getValue("clk").id to LogicVector.of(1, clock.toULong()),
                inputs.getValue("reset").id to LogicVector.of(1, reset.toULong()),
                inputs.getValue("a").id to LogicVector.of(2, a.toULong()),
                inputs.getValue("b").id to LogicVector.of(2, b.toULong()),
            ))
        fun result(state: SimulationState): String {
            assertFalse(state.oscillating, state.diagnostics.toString())
            return state.vectorValues.getValue(outputs.getValue("and_y").id).display +
                state.vectorValues.getValue(outputs.getValue("count").id).display
        }
        var state = sample(SimulationState(), 0)
        assertEquals("1000", result(state))
        for (expected in listOf("1001", "1010", "1011", "1000")) {
            state = sample(state, 1)
            assertEquals(expected, result(state))
            state = sample(state, 0)
        }
        state = sample(state, 0, reset = 1, a = 1, b = 3)
        state = sample(state, 1, reset = 1, a = 1, b = 3)
        assertEquals("0100", result(state))
    }

    @Test fun realDesktopBlifTrisiDrivesInputOnlyWhileControlIsLow() {
        val project = imported("desktop_trisi", "desktop_trisi.blif")
        val inputs = project.mainCircuit.components.filter { it.kind == ComponentKind.INPUT }.associateBy { it.label }
        val output = project.mainCircuit.components.single { it.kind == ComponentKind.OUTPUT }
        val simulator = CircuitSimulator(registry = registry)
        for ((a, b, expected) in listOf(Triple(0, 0, "0"), Triple(1, 0, "1"), Triple(1, 1, "?"), Triple(0, 1, "?"))) {
            val state = simulator.settle(project, vectorInputs = mapOf(
                inputs.getValue("a").id to LogicVector.of(1, a.toULong()),
                inputs.getValue("b").id to LogicVector.of(1, b.toULong()),
            ))
            assertEquals(expected, state.vectorValues.getValue(output.id).display)
        }
    }

    @Test fun tallSubcircuitPortsStaySeparateAcrossLayoutRows() {
        fun bits(start: Int) = (start until start + 10).map { HdlBit.Net(it) }
        val a = bits(2)
        val b = bits(12)
        val child = HdlNetlistModule("child", (0 until 6).map { index ->
            HdlNetlistPort("p$index", PortDirection.INPUT, bits(2 + index * 10))
        } + HdlNetlistPort("y", PortDirection.OUTPUT, bits(52)), emptyList())
        val top = HdlNetlistModule("top", listOf(HdlNetlistPort("a", PortDirection.INPUT, a),
            HdlNetlistPort("b", PortDirection.INPUT, b)) + (0 until 13).map { index ->
            HdlNetlistPort("y$index", PortDirection.OUTPUT, bits(22 + index * 10))
        }, (0 until 13).map { index ->
            HdlNetlistCell("c$index", "child", (0 until 6).associate { port ->
                "p$port" to if (index == 12 && port == 0) b else a
            } + ("y" to bits(22 + index * 10)))
        })
        val project = assertIs<HdlImportResult.Success>(HdlNativeImporter.import(
            HdlNetlist("top", listOf(top, child), "test"), emptyList(), registry = registry)).project
        val inputs = project.mainCircuit.components.filter { it.kind == ComponentKind.INPUT }.associateBy { it.label }
        val outputs = project.mainCircuit.components.filter { it.kind == ComponentKind.OUTPUT }
        val simulator = CircuitSimulator(registry = registry)
        for ((inputA, inputB, expected) in listOf(Triple(0uL, 1023uL, "0000000000"),
            Triple(341uL, 682uL, "0101010101"))) {
            val state = simulator.settle(project, vectorInputs = mapOf(
                inputs.getValue("a").id to LogicVector.of(10, inputA),
                inputs.getValue("b").id to LogicVector.of(10, inputB),
            ))
            assertFalse(state.oscillating, state.diagnostics.toString())
            assertEquals(13, outputs.size)
            for (output in outputs) assertEquals(expected, state.vectorValues.getValue(output.id).display, output.label)
        }
    }
}
